/**
 * Path normalization types for agent session events
 * Handles classification and normalization of file paths from tool events
 */

import type { SystemInfo } from '../adapters/PathNormalizationAdapter';

/**
 * Supported platforms for path normalization
 */
export type SupportedPlatform = 'darwin' | 'linux';

/**
 * Check if platform is supported for path operations
 */
export function isPlatformSupported(platform: string): platform is SupportedPlatform {
  return platform === 'darwin' || platform === 'linux';
}

/**
 * Validate platform support and throw if unsupported
 */
export function validatePlatformSupport(systemInfo: SystemInfo): void {
  if (!isPlatformSupported(systemInfo.platform)) {
    throw new Error(
      `Unsupported platform: ${systemInfo.platform}. ` +
      `Currently only Unix-style paths (darwin, linux) are supported. ` +
      `Windows support is planned for a future release.`
    );
  }
}

/**
 * Repository information for path normalization
 */
export interface RepositoryInfo {
  root: string;
  remoteUrl?: string;
  owner?: string;
  repo?: string;
  branch?: string;
  headCommit?: string; // SHA of the HEAD commit
}

/**
 * Classification of file paths based on their context
 */
export enum PathContext {
  REPO_FILE = 'repo_file', // File within a git repository
  SYSTEM_FILE = 'system_file', // System/library files (e.g., node_modules)
  USER_FILE = 'user_file', // User files outside any repo
  TEMP_FILE = 'temp_file', // Temporary files
  CONFIG_FILE = 'config_file', // Config files (.env, .npmrc, etc.)
}

/**
 * Normalized path information with repository context
 */
export interface NormalizedPathInfo {
  // Original path from the event (as provided by the tool)
  originalPath: string;

  // Absolute path (fully resolved)
  absolutePath: string;

  // Classification context (added back for backward compatibility)
  context: PathContext;

  // Repository context (if file is in a git repository)
  repository?: {
    gitRoot: string; // Absolute path to git root
    relativePath: string; // Path relative to git root
    remoteUrl?: string; // Remote URL if available
    owner?: string; // GitHub/GitLab owner
    repo?: string; // Repository name
  };

  // Display path - relative path if in repo, otherwise absolute path
  displayPath: string;
}

/**
 * File operation types for tracking
 */
export enum FileOperation {
  READ = 'read',
  WRITE = 'write',
  CREATE = 'create',
  DELETE = 'delete',
  EDIT = 'edit',
  SEARCH = 'search',
  LIST = 'list',
}

/**
 * Helper to determine file operation from tool name
 */
export function getFileOperation(toolName: string): FileOperation | undefined {
  const toolNameLower = toolName.toLowerCase();

  if (toolNameLower.includes('read')) return FileOperation.READ;
  if (toolNameLower.includes('write')) return FileOperation.WRITE;
  if (toolNameLower.includes('create')) return FileOperation.CREATE;
  if (toolNameLower.includes('delete') || toolNameLower.includes('remove'))
    return FileOperation.DELETE;
  if (toolNameLower.includes('edit') || toolNameLower.includes('replace'))
    return FileOperation.EDIT;
  if (toolNameLower.includes('grep') || toolNameLower.includes('search'))
    return FileOperation.SEARCH;
  if (toolNameLower.includes('ls') || toolNameLower.includes('list')) return FileOperation.LIST;

  return undefined;
}

/**
 * Extract file paths from tool input based on tool name
 * @deprecated Use extractFilePathsFromTool instead which handles both input and output
 */
export function extractFilePathsFromToolInput(toolName: string, toolInput: any): string[] {
  if (!toolInput || typeof toolInput !== 'object') {
    return [];
  }

  const paths: string[] = [];

  // Handle different tool naming conventions
  switch (toolName) {
    case 'Read':
    case 'Write':
    case 'Edit':
      if (toolInput.file_path) paths.push(toolInput.file_path);
      break;

    case 'MultiEdit':
      if (toolInput.file_path) paths.push(toolInput.file_path);
      // MultiEdit operates on a single file with multiple edits
      break;

    case 'NotebookRead':
    case 'NotebookEdit':
      if (toolInput.notebook_path) paths.push(toolInput.notebook_path);
      break;

    case 'Grep':
    case 'LS':
    case 'Glob':
      if (toolInput.path) paths.push(toolInput.path);
      // Note: Results come from toolOutput, not toolInput
      break;

    // Gemini tools
    case 'read_file': {
      const readPath = toolInput.absolute_path || toolInput.file_path;
      if (readPath) paths.push(readPath);
      break;
    }

    case 'write_file':
    case 'replace':
      if (toolInput.file_path) paths.push(toolInput.file_path);
      break;

    case 'read_many_files':
      if (toolInput.paths && Array.isArray(toolInput.paths)) {
        paths.push(...toolInput.paths);
      }
      break;

    // MCP tools
    default:
      if (toolName.startsWith('mcp_')) {
        // MCP tools use various field names
        const mcpPath = toolInput.filePath || toolInput.file_path || toolInput.path;
        if (mcpPath) paths.push(mcpPath);
      } else {
        // Generic fallback - check common field names
        const genericPath =
          toolInput.file_path ||
          toolInput.filePath ||
          toolInput.path ||
          toolInput.fileName ||
          toolInput.absolute_path;
        if (genericPath) paths.push(genericPath);
      }
  }

  return paths;
}

/**
 * Extract file paths from tool output/response based on tool name
 * Based on audit findings from 23,037 real Claude events
 */
export function extractFilePathsFromToolOutput(toolName: string, toolOutput: any): string[] {
  if (!toolOutput) return [];

  const paths: string[] = [];

  // Handle different tool response structures
  switch (toolName) {
    case 'Read':
      // tool_response.file.filePath (2,365 occurrences)
      if (toolOutput.file?.filePath) {
        paths.push(toolOutput.file.filePath);
      }
      break;

    case 'Edit':
    case 'Write':
    case 'MultiEdit':
      // tool_response.filePath (2,525 occurrences)
      if (toolOutput.filePath) {
        paths.push(toolOutput.filePath);
      }
      break;

    case 'Glob':
      // tool_response can be array of paths or object with filenames
      if (Array.isArray(toolOutput)) {
        paths.push(...toolOutput.filter((p: any) => typeof p === 'string'));
      } else if (toolOutput.filenames && Array.isArray(toolOutput.filenames)) {
        paths.push(...toolOutput.filenames);
      }
      break;

    case 'Grep':
      // Multiple possible formats
      if (typeof toolOutput === 'string') {
        // Parse grep output format: "filename:line:content"
        const lines = toolOutput.split('\n');
        for (const line of lines) {
          const match = line.match(/^([^:]+):/);
          if (match) {
            const filePath = match[1];
            if (!paths.includes(filePath)) {
              paths.push(filePath);
            }
          }
        }
      } else if (Array.isArray(toolOutput)) {
        // Array of file paths
        paths.push(...toolOutput.filter((p: any) => typeof p === 'string'));
      } else if (toolOutput.filenames && Array.isArray(toolOutput.filenames)) {
        // Object with filenames array (331 occurrences)
        paths.push(...toolOutput.filenames);
      } else if (toolOutput.content && typeof toolOutput.content === 'string') {
        // tool_response.content might contain paths (744 occurrences)
        const lines = toolOutput.content.split('\n');
        for (const line of lines) {
          // Try to extract file paths from content
          const match = line.match(/^([^:]+\.[a-zA-Z]+)(?::|$)/);
          if (match) {
            const filePath = match[1];
            if (!paths.includes(filePath)) {
              paths.push(filePath);
            }
          }
        }
      }
      break;

    case 'LS':
      // LS returns array of file/directory names
      if (Array.isArray(toolOutput)) {
        paths.push(...toolOutput.filter((p: any) => typeof p === 'string'));
      } else if (toolOutput.filenames && Array.isArray(toolOutput.filenames)) {
        paths.push(...toolOutput.filenames);
      }
      break;

    case 'Bash':
    case 'BashOutput':
      // tool_response.stdout (670 occurrences) - may contain file paths
      if (toolOutput.stdout && typeof toolOutput.stdout === 'string') {
        // Extract paths that look like files from stdout
        const stdout = toolOutput.stdout;
        // Match paths that start with / or ./ and have extensions
        const pathMatches = stdout.match(/(?:^|\s)(\/[^\s]+\.[a-zA-Z]+|\.\/[^\s]+\.[a-zA-Z]+)/gm);
        if (pathMatches) {
          paths.push(...pathMatches.map((p: string) => p.trim()));
        }
      }
      break;
  }

  return paths;
}

/**
 * Comprehensive path extraction from both tool input and output
 * Combines extraction from all discovered fields based on audit
 * @param toolName The name of the tool
 * @param toolInput The tool's input parameters
 * @param toolOutput The tool's output/response (optional)
 * @param systemInfo System information for platform validation (optional, defaults to Unix)
 * @throws Error if platform is not supported
 */
export function extractFilePathsFromTool(
  toolName: string,
  toolInput: any,
  toolOutput?: any,
  systemInfo?: SystemInfo
): string[] {
  // Validate platform if system info provided
  if (systemInfo) {
    validatePlatformSupport(systemInfo);
  }
  const paths: string[] = [];

  // Extract from input
  if (toolInput) {
    paths.push(...extractFilePathsFromToolInput(toolName, toolInput));

    // Additional extraction from audit findings
    // Check for paths in edits array (MultiEdit)
    if (toolName === 'MultiEdit' && toolInput.edits && Array.isArray(toolInput.edits)) {
      // While edits contain code, we already have the main file_path
      // No additional paths to extract here
    }

    // Check for directory paths (MCP tools)
    if (toolInput.directoryPath) {
      paths.push(toolInput.directoryPath);
    }

    // Check for anchor paths (MCP tools - 42 occurrences)
    if (toolInput.anchors && Array.isArray(toolInput.anchors)) {
      paths.push(...toolInput.anchors.filter((a: any) => typeof a === 'string'));
    }
  }

  // Extract from output
  if (toolOutput) {
    const outputPaths = extractFilePathsFromToolOutput(toolName, toolOutput);
    // Add output paths if not already in the list
    for (const path of outputPaths) {
      if (!paths.includes(path)) {
        paths.push(path);
      }
    }
  }

  // Remove duplicates and return
  return [...new Set(paths)];
}

/**
 * Check if a path is absolute (Unix-style only)
 * @param filePath The file path to check
 * @param systemInfo Optional system info for validation
 * @throws Error if platform is not supported
 */
export function isAbsolutePath(filePath: string, systemInfo?: SystemInfo): boolean {
  // Validate platform if system info provided
  if (systemInfo) {
    validatePlatformSupport(systemInfo);
  }

  // Unix/Mac absolute paths only
  return filePath.startsWith('/');
}

/**
 * Classify a file path based on patterns
 */
export function classifyPath(absolutePath: string): PathContext {
  // Normalize path separators for consistent checking
  const normalizedPath = absolutePath.replace(/\\/g, '/');

  // Check for temp files first (highest priority)
  if (
    normalizedPath.includes('/tmp/') ||
    normalizedPath.includes('/var/folders/') ||
    normalizedPath.includes('/Temp/') ||
    normalizedPath.includes('/temp/') ||
    normalizedPath.includes('/.cache/')
  ) {
    return PathContext.TEMP_FILE;
  }

  // Check for system/dependency files
  if (
    normalizedPath.includes('/node_modules/') ||
    normalizedPath.includes('/vendor/') ||
    normalizedPath.includes('/bower_components/') ||
    normalizedPath.includes('/.pnpm/') ||
    normalizedPath.includes('/site-packages/') ||
    normalizedPath.includes('/dist-packages/')
  ) {
    return PathContext.SYSTEM_FILE;
  }

  // Check for config files
  if (
    normalizedPath.includes('/.env') ||
    normalizedPath.includes('/config') ||
    normalizedPath.includes('/.npmrc') ||
    normalizedPath.includes('/.gitconfig') ||
    normalizedPath.includes('/.ssh/') ||
    normalizedPath.match(/\.(json|yaml|yml|toml|ini|conf|cfg)$/)
  ) {
    return PathContext.CONFIG_FILE;
  }

  // Check for system paths
  if (
    normalizedPath.startsWith('/usr/') ||
    normalizedPath.startsWith('/lib/') ||
    normalizedPath.startsWith('/bin/') ||
    normalizedPath.startsWith('/sbin/') ||
    normalizedPath.startsWith('/etc/') ||
    normalizedPath.startsWith('/System/') || // macOS
    normalizedPath.startsWith('C:/Windows/') ||
    normalizedPath.startsWith('C:/Program Files/')
  ) {
    return PathContext.SYSTEM_FILE;
  }

  // Default to user file
  return PathContext.USER_FILE;
}
